import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Grid,
  Card,
  CardMedia,
  CardContent,
  Button,
  CircularProgress,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
} from '@mui/material';

const mockTemplates = [
  {
    id: 1,
    name: 'Căn hộ Quận 7',
    description: 'Mẫu landing page hiện đại, tối ưu cho dự án căn hộ.',
    price: 350000,
    category: 'Căn hộ',
    image: 'https://via.placeholder.com/400x300.png?text=Apartment+Template',
  },
  {
    id: 2,
    name: 'Biệt thự cao cấp',
    description: 'Thiết kế sang trọng, phù hợp cho biệt thự hoặc nhà phố.',
    price: 500000,
    category: 'Biệt thự',
    image: 'https://via.placeholder.com/400x300.png?text=Villa+Template',
  },
  {
    id: 3,
    name: 'Nhà phố mới xây',
    description: 'Mẫu đơn giản, tập trung vào hình ảnh và thông tin dự án.',
    price: 200000,
    category: 'Nhà phố',
    image: 'https://via.placeholder.com/400x300.png?text=Townhouse+Template',
  },
];

const TemplatesPage = () => {
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [openDialog, setOpenDialog] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setTemplates(mockTemplates);
      setLoading(false);
    }, 1000);
    return () => clearTimeout(timer);
  }, []);

  const handleBuyTemplate = (template) => {
    setOpenDialog(true);
    console.log('Bạn đã chọn mua:', template.name);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 4 }}>
      <Typography variant="h4" gutterBottom>
        Thư viện mẫu Landing Page
      </Typography>
      <Typography variant="body1" sx={{ mb: 4 }}>
        Chọn một trong các mẫu thiết kế chuyên nghiệp hoặc đăng ký gói Premium để sử dụng không giới hạn.
      </Typography>
      <Grid container spacing={4}>
        {templates.map((template) => (
          <Grid item xs={12} sm={6} md={4} key={template.id}>
            <Card sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
              <CardMedia
                component="img"
                height="200"
                image={template.image}
                alt={template.name}
              />
              <CardContent sx={{ flexGrow: 1 }}>
                <Typography gutterBottom variant="h5" component="div">
                  {template.name}
                </Typography>
                <Chip label={template.category} size="small" color="primary" sx={{ mb: 1 }} />
                <Typography variant="body2" color="text.secondary">
                  {template.description}
                </Typography>
                <Box sx={{ mt: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Typography variant="h6" color="success.main">
                    {template.price.toLocaleString('vi-VN')} VNĐ
                  </Typography>
                  <Button variant="contained" onClick={() => handleBuyTemplate(template)}>
                    Mua ngay
                  </Button>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
      >
        <DialogTitle>Thông báo</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Chức năng thanh toán sẽ được xử lý tại đây. Bạn có thể sử dụng Momo hoặc VNPay.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Đóng</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default TemplatesPage;
